select case when s.rating >= 4.2 then 'high' when s.rating >= 2.4 then 'mid' else 'low' end as rating_bucket, s.city, round(stddev(ss.units), 2) as stddev_units, count(ss.units) as units_count from store_sales ss join products p on p.id = ss.product_id join suppliers s on p.supplier_id = s.id group by case when s.rating >= 4.2 then 'high' when s.rating >= 2.4 then 'mid' else 'low' end, s.city order by units_count desc, s.city;
